function A(t){return Array.isArray(t)?t:Array.isArray(t.items)?t.items:Array.isArray(t.data)?t.data:[]}function l(t){if(!Array.isArray(t))return typeof t.total=="number"?t.total:void 0}async function I(t,_){const e=Math.min(Math.max(1,1e3),1e3),c=200,a=[];let n=0;for(let r=0;r<c;r+=1){const i=await t({skip:n,limit:e}),o=A(i);if(a.push(...o),o.length<e)break;const s=l(i);if(typeof s=="number"&&a.length>=s)break;n+=e}return a}async function f(t,_){const e=Math.min(Math.max(1,1e4),1e4),c=200,a=[];let n=1;for(let r=0;r<c;r+=1){const i=await t({current:n,page_size:e}),o=A(i);if(a.push(...o),o.length<e)break;const s=l(i);if(typeof s=="number"&&a.length>=s)break;n+=1}return a}export{f as a,I as f};
